                return "STOP " + x2[:170] + ("  @" + loc if loc else "")
    return "NO OUTPUT: " + " | ".join(lines[:3])[:200]
for comp in sorted(names):
    i, expr = names[comp]
    print(f"{i}\t{summary(segs.get(comp, ['(missing)']))}")
